package android.os; public class Handler {static class Task {Runnable r;long at;Task(Runnable r,long at){this.r=r;this.at=at;}}public java.util.List<Task> tasks=new java.util.ArrayList<>();public boolean post(Runnable r){r.run();return true;}public boolean postDelayed(Runnable r,long delay){tasks.add(new Task(r,SystemClock.now+delay));return true;}public void drain(){int limit=0;while(true){Task next=null;for(Task t:tasks)if(t.at<=SystemClock.now&&(next==null||t.at<next.at))next=t;if(next==null)return;if(++limit>10000)throw new AssertionError("handler loop");tasks.remove(next);next.r.run();}}}